const days = parseInt($json["body"]["days"]);
const futureDate = new Date();
futureDate.setDate(futureDate.getDate() + days);
return [{ json: { futureDate: futureDate.toISOString() } }];

const length = 12;
const charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
let password = "";
for (let i = 0, n = charset.length; i < length; ++i) {
  password += charset.charAt(Math.floor(Math.random() * n));
}
return [{ json: { password } }];

const principal = parseFloat($json["body"]["principal"]);
const annualInterestRate = parseFloat($json["body"]["annualInterestRate"]) / 100 / 12;
const numberOfPayments = parseInt($json["body"]["numberOfPayments"]);
const monthlyPayment = (principal * annualInterestRate) / (1 - Math.pow(1 + annualInterestRate, -numberOfPayments));
return [{ json: { monthlyPayment: monthlyPayment.toFixed(2) } }];
